  const EARLY_GAME_BALANCE=Object.freeze({
    maxLevel:60,
    rescuePattern:"IOITOIOOTLIOTIOT",
    tiers:Object.freeze([
      Object.freeze({to:10,minBufferPieces:24,bufferMultiplier:2.20,maxOccupiedRows:3,fallIntervalMs:1400,lockDelayMs:1000,maxUndos:10,oneStarMinimum:50,twoStarMinimum:65,difficultyMin:10,difficultyMax:20,removeHeavy:true}),
      Object.freeze({to:25,minBufferPieces:20,bufferMultiplier:1.80,maxOccupiedRows:4,fallIntervalMs:1300,lockDelayMs:900,maxUndos:9,oneStarMinimum:50,twoStarMinimum:68,difficultyMin:21,difficultyMax:32,removeHeavy:true}),
      Object.freeze({to:40,minBufferPieces:16,bufferMultiplier:1.50,maxOccupiedRows:5,fallIntervalMs:1200,lockDelayMs:850,maxUndos:8,oneStarMinimum:50,twoStarMinimum:72,difficultyMin:33,difficultyMax:43,removeHeavy:true}),
      Object.freeze({to:50,minBufferPieces:14,bufferMultiplier:1.25,maxOccupiedRows:6,fallIntervalMs:1100,lockDelayMs:800,maxUndos:7,oneStarMinimum:50,twoStarMinimum:75,difficultyMin:44,difficultyMax:54,removeHeavy:true}),
      // Phase 13 transition band: remove assistance gradually rather than all at L51.
      Object.freeze({to:55,minBufferPieces:8,bufferMultiplier:0.70,maxOccupiedRows:7,fallIntervalMs:1050,lockDelayMs:750,maxUndos:7,oneStarMinimum:50,twoStarMinimum:77,difficultyMin:55,difficultyMax:58,removeHeavy:true}),
      Object.freeze({to:60,minBufferPieces:4,bufferMultiplier:0.35,maxOccupiedRows:8,fallIntervalMs:975,lockDelayMs:650,maxUndos:6,oneStarMinimum:50,twoStarMinimum:79,difficultyMin:59,difficultyMax:62,removeHeavy:false})
    ])
  });
  function earlyBalanceForLevel(levelId){
    const id=Number(levelId);if(!(id>=1&&id<=EARLY_GAME_BALANCE.maxLevel))return null;
    const tier=EARLY_GAME_BALANCE.tiers.find(v=>id<=v.to)||EARLY_GAME_BALANCE.tiers[EARLY_GAME_BALANCE.tiers.length-1];
    const previousTo=EARLY_GAME_BALANCE.tiers[EARLY_GAME_BALANCE.tiers.indexOf(tier)-1]?.to||0;
    const span=Math.max(1,tier.to-previousTo),progress=(id-previousTo-1)/Math.max(1,span-1);
    return {...tier,difficultyScore:Math.round(tier.difficultyMin+(tier.difficultyMax-tier.difficultyMin)*progress)};
  }

  // v71 Phase 13: board-informed campaign calibration. Levels 61-750 combine
  // audited board structure (pollution, heavy cells, rocks, queue length and prior
